    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps_of(g,bg):
    seen=set();res=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c];st=[(r,c)];cp=[]
                seen.add((r,c))
                while st:
                    a,b=st.pop();cp.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<len(g) and 0<=y<len(g[0]) and (x,y) not in seen and g[x][y]==col:
                                seen.add((x,y));st.append((x,y))
                res.append((col,cp))
    return res
def bbox(cp):
    rs=[q[0] for q in cp];cs=[q[1] for q in cp]
    return min(rs),max(rs),min(cs),max(cs)
for k in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    gin,gout=G[k+' input'],G[k+' output']
    bg=gin[0][0]
    boxes=[];t=None
    for col,cp in comps_of(gin,bg):
        br=bbox(cp)
        noise=sorted({(rr-br[0],cc-br[2]) for rr in range(br[0]+1,br[1]) for cc in range(br[2]+1,br[3]) if gin[rr][cc]==col})
        if not noise: continue
        if t is None or len(noise)>len(t[1]): t=(noise,col)
        boxes.append((col,br,noise))
    P=t[1]
    out=[row[:] for row in gin]
    for col,(r0,r1,c0,c1),noise in boxes:
        if set(noise)==set(P): continue
        ir,ic=r1-r0,c1-c0
        fits=all(p[0]<=ir-1 and p[1]<=ic-1 for p in noise)
        if fits:
            for dr,dc in noise:
                out[r0+dr][c0+dc]=col
        else:
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    if (r==r0 or r==r1 or c==c0 or c==c1) and gin[r][c]==col:
                        out[r][c]=0
    print(k, out==gout)

