# boxes: components whose bbox border is one color AND interior contains some non-bg cells of same color
def comps(g,bg):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; cp=[]; seen.add((r,c))
                while st:
                    a,b=st.pop(); cp.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<h and 0<=y<w and (x,y) not in seen and g[x][y]==col:
                                seen.add((x,y)); st.append((x,y))
                rs=[p[0] for p in cp]; cs=[p[1] for p in cp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                inn=sum(1 for rr in range(r0+1,r1) for cc in range(c0+1,c1) if g[rr][cc]==col)
                # perimeter must be fully colored (any cell in bbox on boundary belonging to comp)
                per=all(g[r][c]!=bg or (g[r][c]==col if False else True) for r,c in itertools.product(range(r0,r1+1),range(c0,c1+1)) if r in(r0,r1) or c in(c0,c1))
                if per and inn:
                    out.append({'col':col,'r0':r0,'r1':r1,'c0':c0,'c1':c1,'inn':inn})
    return out
