G=load(); print(len(G['Test input']),len(G['Test input'][0]))

import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def boxes(g,bg=0):
    h=len(g);w=len(g[0]);seen=set();out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c];st=[(r,c)];cp=[];seen.add((r,c))
                while st:
                    a,bv=st.pop();cp.append((a,bv))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,bv+db
                            if 0<=x<h and 0<=y<w and (x,y) not in seen and g[x][y]==col:
                                seen.add((x,y));st.append((x,y))
                rs=[p[0] for p in cp];cs=[p[1] for p in cp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                inn=sum(1 for rr in range(r0+1,r1) for cc in range(c0+1,c1) if g[rr][cc]==col)
                out.append({'col':col,'r0':r0,'r1':r1,'c0':c0,'c1':c1,'inn':inn})
    return out
def solve(g):
    bg=0; b=boxes(g)
    tm=max(b,key=lambda x:x['inn'])
    Ht,Wt=tm['r1']-tm['r0']+1, tm['c1']-tm['c0']+1
    P=sorted({(rr-tm['r0'],cc-tm['c0']) for rr in range(tm['r0']+1,tm['r1']) for cc in range(tm['c0']+1,tm['c1']) if g[rr][cc]==tm['col']})
    out=[row[:] for row in g]
    for bb in b:
        if bb is tm or (bb['r1']-bb['r0']+1>=Ht and bb['c1']-bb['c0']+1>=Wt):
            for dr,dc in P:
                out[bb['r0']+dr][bb['c0']+dc]=bb['col']
        else:
            for r in range(bb['r0'],bb['r1']+1):
                for c in range(bb['c0'],bb['c1']+1):
                    if out[r][c]==bb['col']: out[r][c]=bg
    return out
assert solve(G['Demo pair 1 input'])==G['Demo pair 1 output']
assert solve(G['Demo pair 2 input'])==G['Demo pair 2 output']
assert solve(G['Demo pair 3 input'])==G['Demo pair 3 output']
o=solve(G['Test input'])
print(len(o),len(o[0]))
s=json.dumps(o,separators=(',',':'))
